<script setup lang="ts">
import { reactive, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { useAuthenticationStore } from '../../stores/authentication/store'
import { userService } from '../../services/user/service'
import { userError } from '../../utils/errors'

const auth = useAuthenticationStore()
const router = useRouter()
const profile = reactive({ name: auth.user?.name || '', first_name: auth.user?.first_name || '', telephone: auth.user?.telephone || '', address: auth.user?.address || '' })
const passwords = reactive({ current_password: '', new_password: '' })
const saving = ref(false)
const changingPassword = ref(false)
const error = ref('')
const success = ref('')

async function saveProfile() {
  saving.value = true; error.value = ''; success.value = ''
  try { auth.user = await userService.updateMe(profile); success.value = 'Vos informations ont été mises à jour.' } catch (value) { error.value = userError(value, 'Impossible de mettre à jour votre profil.', 'CLIENT_PROFILE_ERROR') } finally { saving.value = false }
}
async function changePassword() {
  changingPassword.value = true; error.value = ''; success.value = ''
  try { await userService.changePassword(passwords); passwords.current_password = ''; passwords.new_password = ''; success.value = 'Votre mot de passe a été modifié. Les autres sessions ont été fermées.' } catch (value) { error.value = userError(value, 'Impossible de modifier le mot de passe.', 'CLIENT_PASSWORD_ERROR') } finally { changingPassword.value = false }
}
function goBack() { void router.push({ name: 'client-space' }) }
</script>

<template>
  <main class="profile-page"><header class="profile-header"><RouterLink class="profile-brand" to="/"><span class="profile-brand-mark">C</span><span>Coopérative</span></RouterLink><nav><RouterLink to="/espace-client">Mon espace</RouterLink><RouterLink to="/mes-reservations">Mes réservations</RouterLink><RouterLink to="/mes-billets">Mes billets</RouterLink></nav></header><section class="profile-shell"><RouterLink class="profile-back" to="/espace-client">← Retour à mon espace</RouterLink><p class="profile-kicker">MON PROFIL</p><h1>Vos informations personnelles</h1><p class="profile-lead">Ces informations servent à vous contacter au sujet de vos réservations.</p><p v-if="error" class="profile-message error" role="alert">{{ error }}</p><p v-if="success" class="profile-message success" role="status">{{ success }}</p><div class="profile-grid"><form class="profile-card" @submit.prevent="saveProfile"><h2>Informations du compte</h2><label for="profile-first-name">Prénom</label><input id="profile-first-name" v-model="profile.first_name" required autocomplete="given-name" /><label for="profile-name">Nom</label><input id="profile-name" v-model="profile.name" required autocomplete="family-name" /><label for="profile-email">Adresse email</label><input id="profile-email" :value="auth.user?.email" disabled aria-describedby="email-note" /><small id="email-note">L’adresse email ne peut pas être modifiée ici.</small><label for="profile-phone">Téléphone</label><input id="profile-phone" v-model="profile.telephone" autocomplete="tel" /><label for="profile-address">Adresse</label><textarea id="profile-address" v-model="profile.address" rows="3" autocomplete="street-address"></textarea><button class="profile-primary" type="submit" :disabled="saving">{{ saving ? 'Enregistrement…' : 'Enregistrer mes informations' }}</button></form><form class="profile-card" @submit.prevent="changePassword"><h2>Sécurité</h2><p class="profile-card-intro">Choisissez un mot de passe personnel et ne le partagez jamais.</p><label for="current-password">Mot de passe actuel</label><input id="current-password" v-model="passwords.current_password" type="password" required autocomplete="current-password" /><label for="new-password">Nouveau mot de passe</label><input id="new-password" v-model="passwords.new_password" type="password" required minlength="8" autocomplete="new-password" /><button class="profile-primary" type="submit" :disabled="changingPassword">{{ changingPassword ? 'Modification…' : 'Modifier le mot de passe' }}</button><button class="profile-secondary" type="button" @click="goBack">Annuler</button></form></div></section></main>
</template>

<style scoped>
.profile-page { min-height: 100vh; color: #18324b; background: #f4f7fb; font-family: Inter, system-ui, sans-serif; }.profile-header { display: flex; align-items: center; gap: 2rem; padding: .85rem max(1rem, calc((100vw - 1240px) / 2)); border-bottom: 1px solid #e4ecf2; background: #fff; }.profile-brand { display: inline-flex; align-items: center; gap: .6rem; color: #0d2b4f; font-weight: 800; text-decoration: none; }.profile-brand-mark { display: grid; place-items: center; width: 2.15rem; height: 2.15rem; border-radius: .55rem; color: #fff; background: #ef8d2f; }.profile-header nav { display: flex; gap: 1.2rem; margin-left: auto; }.profile-header nav a, .profile-back { color: #607487; font-size: .78rem; font-weight: 800; text-decoration: none; }.profile-header nav a:hover, .profile-back:hover { color: #e9782a; }.profile-shell { max-width: 1050px; margin: auto; padding: 3rem 1rem 5rem; }.profile-back { display: inline-block; margin-bottom: 2rem; }.profile-kicker { margin: 0 0 .55rem; color: #e9782a; font-size: .7rem; font-weight: 900; letter-spacing: .15em; }.profile-shell h1 { margin: 0; color: #123452; font: 800 clamp(2rem, 4vw, 3rem) Manrope, sans-serif; letter-spacing: -.06em; }.profile-lead { color: #718596; }.profile-message { padding: .8rem 1rem; border-radius: .4rem; font-size: .82rem; }.profile-message.error { color: #a43f36; background: #fff0ed; }.profile-message.success { color: #276d4e; background: #e9f8ef; }.profile-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.2rem; margin-top: 1.5rem; }.profile-card { display: grid; align-content: start; gap: .45rem; padding: 1.4rem; border: 1px solid #e1e9ef; border-radius: .7rem; background: white; box-shadow: 0 10px 25px #18324b0b; }.profile-card h2 { margin: 0 0 .8rem; color: #123452; font: 800 1.2rem Manrope, sans-serif; }.profile-card label { margin-top: .5rem; color: #536d81; font-size: .75rem; font-weight: 800; }.profile-card input, .profile-card textarea { width: 100%; padding: .7rem; border: 1px solid #d9e3eb; border-radius: .35rem; color: #18324b; background: white; font: inherit; }.profile-card input:disabled { color: #8393a0; background: #f4f7f9; }.profile-card small, .profile-card-intro { color: #8192a1; font-size: .72rem; line-height: 1.5; }.profile-primary, .profile-secondary { min-height: 42px; margin-top: 1rem; border-radius: .4rem; font-weight: 800; cursor: pointer; }.profile-primary { border: 0; color: #fff; background: #ef7828; }.profile-primary:disabled { opacity: .6; cursor: wait; }.profile-secondary { border: 1px solid #d9e3eb; color: #607487; background: #fff; }@media (max-width: 650px) { .profile-header nav { display: none; }.profile-header { justify-content: space-between; }.profile-shell { padding: 2rem 1rem 3rem; }.profile-grid { grid-template-columns: 1fr; } }
</style>
